/** 
 * Send a command to the IRC server.
 * @param contact the chat room
 * @param message the command message
 * @throws UnsupportedCommandException for unknown or unsupported commands
 * @throws BadCommandException in case of a bad command implementation
 * @throws BadCommandInvocationException in case of bad usage of thecommand. An exception will be thrown that contains the root cause and optionally a help text containing usage information for that particular command.
 */
public void command(final Contact contact,final MessageIrcImpl message) throws UnsupportedCommandException, BadCommandException, BadCommandInvocationException {
  if (!this.connectionState.isConnected()) {
    throw new IllegalStateException("Not connected to IRC server.");
  }
  command(contact.getAddress(),message.getContent());
}
